// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/platform", wrapper.GetPlatform)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/platform/nodes", wrapper.ListNodes)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/platform/services", wrapper.ListSharedServices)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/platform/backups", wrapper.GetBackupStatus)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects", wrapper.ListProjects)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects/{project}", wrapper.GetProject)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects/{project}/releases", wrapper.ListReleases)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects/{project}/workloads", wrapper.ListWorkloads)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects/{project}/workloads/{pod}/logs", wrapper.GetWorkloadLogs)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects/{project}/database", wrapper.GetDatabase)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects/{project}/database/tables", wrapper.ListTables)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects/{project}/database/tables/{table}/rows", wrapper.ListRows)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects/{project}/database/activity", wrapper.GetDatabaseActivity)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects/{project}/storage", wrapper.GetStorage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects/{project}/storage/policy", wrapper.GetStoragePolicy)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects/{project}/auth", wrapper.GetAuth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects/{project}/domains", wrapper.ListProjectDomains)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/platform/edge", wrapper.GetEdge)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/observability", wrapper.GetObservability)

	return m
}
